51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
105	        this.clinicService.saveOwner(owner, sharesHousehold);
106	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
107	        headers.setLocation(UriComponentsBuilder.newInstance()
108	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
109	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
115	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
116	        if (currentOwner == null) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        currentOwner.setAddress(ownerFieldsDto.getAddress());
120	        currentOwner.setCity(ownerFieldsDto.getCity());
121	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
122	        currentOwner.setLastName(ownerFieldsDto.getLastName());
123	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
124	        currentOwner.setEmail(ownerFieldsDto.getEmail());
125	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
126	        this.clinicService.saveOwner(currentOwner);
127	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Transactional
132	    @Override
133	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        this.clinicService.deleteOwner(owner);
139	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
140	    }
141	
142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
145	        Owner owner = this.clinicService.findOwnerById(ownerId);
146	        if (owner == null) {
147	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
148	        }
149	        HttpHeaders headers = new HttpHeaders();
150	        Pet pet = petMapper.toPet(petFieldsDto);
151	        owner.setId(ownerId);
152	        pet.setOwner(owner);
153	        pet.getType().setName(null);
154	        this.clinicService.savePet(pet);
155	        PetDto petDto = petMapper.toPetDto(pet);
156	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
157	            .buildAndExpand(pet.getId()).toUri());
158	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
164	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
165	        if (currentOwner != null) {
166	            Pet currentPet = this.clinicService.findPetById(petId);
167	            if (currentPet != null) {
168	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
169	                currentPet.setName(petFieldsDto.getName());
170	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
171	                this.clinicService.savePet(currentPet);
172	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
173	            }
174	        }
175	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
181	        HttpHeaders headers = new HttpHeaders();
182	        Visit visit = visitMapper.toVisit(visitFieldsDto);
183	        Pet pet = new Pet();
184	        pet.setId(petId);
185	        visit.setPet(pet);
186	        this.clinicService.saveVisit(visit);
187	        VisitDto visitDto = visitMapper.toVisitDto(visit);
188	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
189	            .buildAndExpand(visit.getId()).toUri());
190	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
191	    }
192	
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
197	        Owner owner = this.clinicService.findOwnerById(ownerId);
198	        if (owner != null) {
199	            Pet pet = owner.getPet(petId);
200	            if (pet != null) {
201	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
202	            }
203	        }
204	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
205	    }
206	}
