147	    }
148	
149	    /**
150	     * Normalize an email to its canonical stored form, which is lower-cased. This is the single
151	     * source of truth for how an email is persisted, so inputs that differ only in letter case
152	     * are stored identically. Applied by {@link #setEmail(String)} so every persistence path
153	     * (create and update, mapper or hand-copied) stores the same canonical value.
154	     *
155	     * @param email the raw email, possibly {@code null}
156	     * @return the lower-cased form, or {@code null} if the input was {@code null}
157	     */
158	    public static String normalizeEmail(String email) {
159	        return email == null ? null : email.toLowerCase();
160	    }
161	
162	    /**
163	     * Normalize a telephone to its canonical E.164 stored form. This is the single source of
164	     * truth for how a telephone is compared and persisted, so inputs that differ only in
165	     * formatting (spaces, dashes, brackets) are treated as the same number.
166	     *
167	     * <p>The rules are:
168	     * <ul>
169	     *   <li>spaces, dashes and brackets are stripped;</li>
170	     *   <li>a leading {@code '+'} and its country code are kept as given;</li>
171	     *   <li>otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
172	     *       is dropped from the national digits;</li>
173	     *   <li>the result must have 8 to 15 digits after the {@code '+'};</li>
174	     *   <li>for a recognized country code the national number (the digits after the country
175	     *       code) must have the length that code requires: {@code '+61'} requires 9 national
176	     *       digits and {@code '+1'} requires 10.</li>
177	     * </ul>
178	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}. Already-normalized
179	     * values are returned unchanged.
180	     *
181	     * @param telephone the raw telephone, possibly {@code null}
182	     * @return the E.164 form, or {@code null} if the input is {@code null} or cannot form a
183	     *     valid E.164 number
184	     */
185	    public static String normalizeTelephone(String telephone) {
186	        if (telephone == null) {
187	            return null;
188	        }
189	        String trimmed = telephone.trim();
190	        boolean hasCountryCode = trimmed.startsWith("+");
191	        // Strip spaces, dashes and brackets; a leading '+' (if any) is left in place.
192	        String stripped = trimmed.replaceAll("[\\s\\-()]", "");
193	        if (hasCountryCode) {
194	            stripped = stripped.substring(1);
195	        }
196	        if (!stripped.matches("\\d+")) {
197	            return null;
198	        }
199	        String digits;
200	        if (hasCountryCode) {
201	            digits = stripped;
202	        } else {
203	            if (stripped.startsWith("0")) {
204	                stripped = stripped.substring(1);
205	            }
206	            digits = "61" + stripped;
207	        }
208	        if (digits.length() < 8 || digits.length() > 15) {
209	            return null;
210	        }
211	        if (!hasValidNationalNumberLength(digits)) {
212	            return null;
213	        }
214	        return "+" + digits;
215	    }
216	
217	    /**
218	     * Required national-number length (the count of digits after the country code) for each
219	     * recognized country code, longest country code first so the prefix match is unambiguous.
220	     */
221	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = new LinkedHashMap<>();
222	    static {
223	        NATIONAL_NUMBER_LENGTHS.put("61", 9);
224	        NATIONAL_NUMBER_LENGTHS.put("1", 10);
225	    }
226	
227	    /**
228	     * Check that the national number of an E.164 digit string (no leading {@code '+'}) has the
229	     * length its country code requires. A country code with no registered length places no
230	     * additional constraint and is accepted.
231	     *
232	     * @param digits the E.164 digits without the leading {@code '+'}
233	     * @return {@code true} if the national-number length is valid for the country code
234	     */
235	    private static boolean hasValidNationalNumberLength(String digits) {
236	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTHS.entrySet()) {
237	            String countryCode = entry.getKey();
238	            if (digits.startsWith(countryCode)) {
239	                return digits.length() - countryCode.length() == entry.getValue();
240	            }
241	        }
242	        return true;
243	    }
244	
245	    /**
246	     * Common street-type abbreviations expanded by {@link #normalizeAddress(String)}, keyed by the
247	     * upper-cased abbreviation.
248	     */
249	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
250	        "ST", "STREET",
251	        "RD", "ROAD",
252	        "AVE", "AVENUE");
253	
254	    /**
255	     * Normalize an address to its canonical stored form. Leading and trailing whitespace is
256	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
257	     * and common street-type abbreviations are expanded as whole words ({@code ST}->{@code STREET},
258	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). This is the single source of truth for
259	     * how an address is persisted and compared, so inputs that differ only in letter case, spacing
260	     * or abbreviation are treated as the same address. Applied by {@link #setAddress(String)} so
261	     * every persistence path (create and update, mapper or hand-copied) stores the same canonical
262	     * value. The transform is idempotent: a normalized address normalizes to itself.
263	     *
264	     * @param address the raw address, possibly {@code null}
265	     * @return the normalized form, or {@code null} if the input was {@code null}
266	     */
267	    public static String normalizeAddress(String address) {
268	        if (address == null) {
269	            return null;
270	        }
271	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
272	        if (collapsed.isEmpty()) {
273	            return collapsed;
274	        }
275	        String[] tokens = collapsed.split(" ");
276	        StringBuilder normalized = new StringBuilder(collapsed.length());
277	        for (int i = 0; i < tokens.length; i++) {
278	            if (i > 0) {
279	                normalized.append(' ');
280	            }
281	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
282	        }
283	        return normalized.toString();
284	    }
285	
286	    /**
287	     * Normalize a household field (such as last name or address) to its canonical form for
288	     * duplicate-household comparison. Leading and trailing whitespace is trimmed, internal runs
289	     * of whitespace are collapsed to a single space, and the result is lower-cased, so inputs
290	     * that differ only in letter case or spacing are treated as the same value.
291	     *
292	     * @param value the raw field value, possibly {@code null}
293	     * @return the normalized form, or {@code null} if the input was {@code null}
294	     */
295	    public static String normalizeHousehold(String value) {
296	        if (value == null) {
297	            return null;
298	        }
299	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
300	    }
301	
302	    /**
303	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
304	     * last name (compared case-insensitively with collapsed whitespace, see
305	     * {@link #normalizeHousehold(String)}) and the same normalized address (see
306	     * {@link #normalizeAddress(String)}). The value is deterministic in those two fields, so two
307	     * owners who share a household are assigned the same id. It is formatted {@code 'HH-<HEX12>'}
308	     * where {@code HEX12} is the first twelve upper-cased hex characters of the SHA-256 digest of
309	     * the normalized last name and address.
310	     *
311	     * @param lastName the owner's last name, possibly {@code null}
312	     * @param address the owner's address, possibly {@code null}
313	     * @return the household id, or {@code null} if either field is {@code null}
314	     */
315	    public static String householdId(String lastName, String address) {
316	        String normalizedLastName = normalizeHousehold(lastName);
317	        String normalizedAddress = normalizeAddress(address);
318	        if (normalizedLastName == null || normalizedAddress == null) {
319	            return null;
320	        }
321	        String key = normalizedLastName + "\n" + normalizedAddress;
322	        try {
323	            byte[] digest = MessageDigest.getInstance("SHA-256")
324	                .digest(key.getBytes(StandardCharsets.UTF_8));
325	            StringBuilder hex = new StringBuilder(digest.length * 2);
326	            for (byte b : digest) {
327	                hex.append(String.format("%02x", b));
328	            }
329	            return "HH-" + hex.substring(0, 12).toUpperCase();
330	        } catch (NoSuchAlgorithmException e) {
331	            // SHA-256 is a standard algorithm required to be present on every JVM.
332	            throw new IllegalStateException("SHA-256 not available", e);
333	        }
334	    }
335	
336	    /**
337	     * Compute an owner's {@code identityKey}, the single derived value through which all
338	     * duplicate detection is now expressed. It consolidates the three formerly separate
339	     * telephone, email and household duplicate checks into one key, formatted as
340	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}:
341	     * <ul>
342	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
343	     *   <li>the normalized email (see {@link #normalizeEmail(String)}), or the empty string
344	     *       when no email is present, and</li>
345	     *   <li>the household id (see {@link #householdId(String, String)}).</li>
346	     * </ul>
347	     * A {@code null} component is rendered as the empty string. Two owners are the same identity
348	     * only when their <em>whole</em> keys are equal; because the telephone is part of the key, two
349	     * members of the same household with different telephones have different keys.
350	     *
351	     * @param telephone the owner's raw telephone, possibly {@code null}
352	     * @param email the owner's email, possibly {@code null}
353	     * @param lastName the owner's last name, possibly {@code null}
354	     * @param address the owner's address, possibly {@code null}
355	     * @return the identity key, never {@code null}
356	     */
357	    public static String identityKey(String telephone, String email, String lastName, String address) {
358	        String normalizedTelephone = normalizeTelephone(telephone);
359	        String normalizedEmail = normalizeEmail(email);
360	        String household = householdId(lastName, address);
361	        return (normalizedTelephone == null ? "" : normalizedTelephone)
362	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
363	            + "|" + (household == null ? "" : household);
364	    }
