366	    /**
367	     * Build an owner's {@code membershipNumber}, the stable membership identifier derived from the
368	     * owner's own persisted fields. It is formatted {@code '<customerCode>-M<YY>'} where {@code YY}
369	     * is the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}). The
370	     * value is deterministic in those two fields.
371	     *
372	     * @param customerCode the owner's customer code, possibly {@code null}
373	     * @param registrationDate the owner's registration date, possibly {@code null}
374	     * @return the membership number, or {@code null} if either field is {@code null}
375	     */
376	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
377	        if (customerCode == null || registrationDate == null) {
378	            return null;
379	        }
380	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
381	    }
