44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity already exists";
60	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
61	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners has already been registered today";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DuplicateIdentityException}, raised when an owner is saved whose derived
113	     * {@code identityKey} (the single key consolidating the former telephone, email and household
114	     * duplicate checks) already belongs to another owner, by returning a 409 Conflict status.
115	     *
116	     * @param e The {@link DuplicateIdentityException} to be handled
117	     * @param request {@link HttpServletRequest} object referring to the current request.
118	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
119	     */
120	    @ExceptionHandler(DuplicateIdentityException.class)
121	    @ResponseBody
122	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
123	        logger.warn("Duplicate identity at {} {}: {}",
124	            request.getMethod(),
125	            request.getRequestURI(),
126	            e.getMessage());
127	        HttpStatus status = HttpStatus.CONFLICT;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles {@link CityAtCapacityException}, raised when a new owner is created whose city already
134	     * contains the maximum number of owners, by returning a 409 Conflict status.
135	     *
136	     * @param e The {@link CityAtCapacityException} to be handled
137	     * @param request {@link HttpServletRequest} object referring to the current request.
138	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
139	     */
140	    @ExceptionHandler(CityAtCapacityException.class)
141	    @ResponseBody
142	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
143	        logger.warn("City at capacity at {} {}: {}",
144	            request.getMethod(),
145	            request.getRequestURI(),
146	            e.getMessage());
147	        HttpStatus status = HttpStatus.CONFLICT;
148	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
149	        return ResponseEntity.status(status).body(detail);
150	    }
151	
152	    /**
153	     * Handles {@link DailyRegistrationLimitException}, raised when a new owner is created on a day
154	     * that already has the maximum number of owners registered (counted by {@code registrationDate}),
155	     * by returning a 429 Too Many Requests status.
156	     *
157	     * @param e The {@link DailyRegistrationLimitException} to be handled
158	     * @param request {@link HttpServletRequest} object referring to the current request.
159	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
160	     */
161	    @ExceptionHandler(DailyRegistrationLimitException.class)
162	    @ResponseBody
163	    public ResponseEntity<ProblemDetail> handleDailyRegistrationLimitException(DailyRegistrationLimitException e, HttpServletRequest request) {
164	        logger.warn("Daily registration limit reached at {} {}: {}",
165	            request.getMethod(),
166	            request.getRequestURI(),
167	            e.getMessage());
168	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
169	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
170	        return ResponseEntity.status(status).body(detail);
171	    }
172	
173	    /**
174	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
175	     * method returns a 404 Not Found status if an entity does not exist.
176	     *
177	     * @param e The {@link DataIntegrityViolationException} to be handled
178	     * @param request {@link HttpServletRequest} object referring to the current request.
179	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
180	     */
181	    @ExceptionHandler(DataIntegrityViolationException.class)
182	    @ResponseBody
183	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
184	        logger.warn("Data integrity violation at {} {}: {}",
185	            request.getMethod(),
186	            request.getRequestURI(),
187	            e.getMessage());
188	        logger.debug("Data integrity violation stacktrace", e);
189	        HttpStatus status = HttpStatus.NOT_FOUND;
190	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
191	        return ResponseEntity.status(status).body(detail);
192	    }
193	
194	    /**
195	     * Handles exception thrown by Bean Validation on controller methods parameters
196	     *
197	     * @param e The {@link MethodArgumentNotValidException} to be handled
198	     * @param request {@link HttpServletRequest} object referring to the current request.
199	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
200	     */
201	    @ExceptionHandler(MethodArgumentNotValidException.class)
202	    @ResponseBody
203	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
204	        HttpStatus status = HttpStatus.BAD_REQUEST;
205	        BindingErrorsResponse errors = new BindingErrorsResponse();
206	        BindingResult bindingResult = e.getBindingResult();
207	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
208	        if (bindingResult.hasErrors()) {
209	            errors.addAllErrors(bindingResult);
210	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
211	                .map(fieldError -> {
212	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
213	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
214	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
215	                        fieldError.getField(),
216	                        defaultMessage,
217	                        rejectedValue);
218	                    return new ValidationMessageDto(message)
219	                        .putAdditionalProperty("field", fieldError.getField())
220	                        .putAdditionalProperty("rejectedValue", rejectedValue)
221	                        .putAdditionalProperty("defaultMessage", defaultMessage);
222	                })
223	                .toList();
224	            logger.debug("Validation error at {} {}: {}",
225	                request.getMethod(),
226	                request.getRequestURI(),
227	                bindingResult.getFieldErrors());
228	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
229	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
230	                .map(FieldError::getField)
231	                .distinct()
232	                .toList();
233	            detail.setProperty("errors", invalidFields);
234	            return ResponseEntity.status(status).body(detail);
235	        }
236	        return ResponseEntity.status(status).body(detail);
237	    }
238	
239	}
