2	
3	import jakarta.validation.ConstraintValidator;
4	import jakarta.validation.ConstraintValidatorContext;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Validates that an owner's optional postcode is valid for its city. The check delegates to
11	 * {@link Owner#isPostcodeValidForCity(String, String)}, the single source of truth for postcode
12	 * validity, so an absent postcode is accepted while a present one must be four digits and within
13	 * the range of the city's region. On failure the violation is reported against the {@code postcode}
14	 * field so the error response names it.
15	 */
16	public class PostcodeValidator implements ConstraintValidator<PostcodeValidation, OwnerFieldsDto> {
17	
18	    @Override
19	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
20	        if (owner == null) {
21	            return true;
22	        }
23	        if (Owner.isPostcodeValidForCity(owner.getPostcode(), owner.getCity())) {
24	            return true;
25	        }
26	        context.disableDefaultConstraintViolation();
27	        context.buildConstraintViolationWithTemplate(context.getDefaultConstraintMessageTemplate())
28	            .addPropertyNode("postcode")
29	            .addConstraintViolation();
30	        return false;
31	    }
32	}
