269	    /**
270	     * Save an owner, enforcing the create-time business rules.
271	     *
272	     * <p>The {@code sharesHousehold} flag is retained only for backward compatibility and is now a
273	     * no-op: it formerly bypassed a dedicated duplicate-household check, but duplicate detection is
274	     * now expressed solely through {@link #assertIdentityIsUnique(Owner)}, under which members of the
275	     * same household with different telephones are always allowed, so the flag has nothing to bypass.
276	     */
277	    @Override
278	    @Transactional
279	    public void saveOwner(Owner owner, boolean sharesHousehold) throws DataAccessException {
280	        boolean isCreate = owner.isNew();
281	        assertIdentityIsUnique(owner);
282	        if (owner.isNew()) {
283	            assertCityHasCapacity(owner);
284	        }
285	        if (owner.getRegistrationDate() == null) {
286	            owner.setRegistrationDate(LocalDate.now());
287	        }
288	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
289	        if (owner.isNew()) {
290	            assertDailyRegistrationLimit(owner);
291	            owner.setBulkSignupWarning(computeBulkSignupWarning(owner));
292	        }
293	        if (owner.isNew() && owner.getCustomerCode() == null) {
294	            owner.setCustomerCode(generateCustomerCode(owner));
295	        }
296	        if (owner.isNew() && owner.getNamesakeCount() == null) {
297	            owner.setNamesakeCount(countNamesakes(owner));
298	        }
299	        ownerRepository.save(owner);
300	        if (isCreate) {
301	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
302	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
303	        }
304	    }
305	
306	    /**
307	     * Count the existing owners that, at the moment this owner is created, share its first name
308	     * and last name (both compared case-insensitively). The owner being saved is excluded by id so
309	     * it never counts itself. This value is deterministic given the current data, so it is computed
310	     * once at creation time and stored.
311	     */
312	    private Integer countNamesakes(Owner owner) {
313	        String firstName = owner.getFirstName();
314	        String lastName = owner.getLastName();
315	        if (firstName == null || lastName == null) {
316	            return 0;
317	        }
318	        return (int) ownerRepository.findAll().stream()
319	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
320	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
321	                && lastName.equalsIgnoreCase(existing.getLastName()))
322	            .count();
323	    }
324	
325	    /**
326	     * Build an owner's {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where
327	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} the
328	     * upper-cased first three letters of the last name, and {@code NNNN} a per-city, 4-digit
329	     * zero-padded sequence equal to one more than the number of owners already in that city
330	     * (e.g. {@code 'LON-SMI-0007'}).
331	     */
332	    private String generateCustomerCode(Owner owner) {
333	        String city = owner.getCity();
334	        String city3 = codePrefix(city);
335	        String last3 = codePrefix(owner.getLastName());
336	        long sequence = ownerRepository.findAll().stream()
337	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
338	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
339	            .count() + 1L;
340	        return String.format("%s-%s-%04d", city3, last3, sequence);
341	    }
342	
343	    /**
344	     * Build a {@code customerCode} segment from {@code value}: its first three characters
345	     * (fewer if it is shorter), upper-cased.
346	     */
347	    private static String codePrefix(String value) {
348	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
349	    }
350	
351	    /**
352	     * Enforce that no <em>other</em> owner already shares this owner's derived identity, throwing
353	     * {@link DuplicateIdentityException} if one does. This single check consolidates the former
354	     * separate telephone, email and household duplicate checks into the one {@code identityKey}
355	     * (normalized telephone, normalized email (or empty) and household id, see
356	     * {@link Owner#identityKey(String, String, String, String)}).
357	     *
358	     * <p>Because the telephone is part of the key, two owners can only ever collide on the whole
359	     * key when their normalized telephones already match; the normalized telephone is therefore the
360	     * decisive component and is what this check compares. Consequently two members of the same
361	     * household with different telephones have different identity keys and are both allowed, while
362	     * an owner reusing an existing normalized telephone is rejected. The owner being saved is
363	     * excluded by id so updating an owner in place never conflicts with itself.
364	     */
365	    private void assertIdentityIsUnique(Owner owner) {
366	        String normalizedTelephone = Owner.normalizeTelephone(owner.getTelephone());
367	        if (normalizedTelephone == null) {
368	            return;
369	        }
370	        boolean duplicate = ownerRepository.findAll().stream()
371	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
372	            .map(existing -> Owner.normalizeTelephone(existing.getTelephone()))
373	            .anyMatch(normalizedTelephone::equals);
374	        if (duplicate) {
375	            throw new DuplicateIdentityException(Owner.identityKey(
376	                owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getAddress()));
377	        }
378	    }
379	
380	    /**
381	     * Enforce that the owner's city has not yet reached its capacity, throwing
382	     * {@link CityAtCapacityException} when the city (compared case-insensitively) already contains
383	     * {@link #MAX_OWNERS_PER_CITY} or more owners. The owner being saved is excluded by id.
384	     */
385	    private void assertCityHasCapacity(Owner owner) {
386	        String city = owner.getCity();
387	        if (city == null) {
388	            return;
389	        }
390	        long count = ownerRepository.findAll().stream()
391	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
392	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
393	            .count();
394	        if (count >= MAX_OWNERS_PER_CITY) {
395	            throw new CityAtCapacityException(city);
396	        }
397	    }
398	
399	    /**
400	     * Roll a registration date forward to the next business day. A date that falls on a Saturday or
401	     * Sunday is advanced to the following Monday; a weekday is returned unchanged. This is applied to
402	     * the effective registration date (whether supplied in the request or defaulted to the server
403	     * date) so that every value derived from it&mdash;such as the membership number's year segment
404	     * and the daily create-limit counting&mdash;uses the adjusted business day.
405	     */
406	    private static LocalDate rollToBusinessDay(LocalDate date) {
407	        if (date == null) {
408	            return null;
409	        }
410	        DayOfWeek dayOfWeek = date.getDayOfWeek();
411	        if (dayOfWeek == DayOfWeek.SATURDAY) {
412	            return date.plusDays(2);
413	        }
414	        if (dayOfWeek == DayOfWeek.SUNDAY) {
415	            return date.plusDays(1);
416	        }
417	        return date;
418	    }
419	
420	    /**
421	     * Enforce that the owner's registration day has not yet reached its capacity, throwing
422	     * {@link DailyRegistrationLimitException} when {@link #MAX_OWNERS_PER_DAY} or more owners are
423	     * already registered on that day (counted by {@code registrationDate}). The owner being saved
424	     * is excluded by id.
425	     */
426	    private void assertDailyRegistrationLimit(Owner owner) {
427	        LocalDate registrationDate = owner.getRegistrationDate();
428	        if (registrationDate == null) {
429	            return;
430	        }
431	        long count = ownerRepository.findAll().stream()
432	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
433	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
434	            .count();
435	        if (count >= MAX_OWNERS_PER_DAY) {
436	            throw new DailyRegistrationLimitException(registrationDate);
437	        }
438	    }
439	
440	    /**
441	     * Compute whether a newly created owner should carry a bulk-signup warning, i.e. whether more
442	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created on this owner's
443	     * registration day (counted by {@code registrationDate}, excluding the owner being saved). Like
444	     * the daily-limit rule this reflects the state at creation time, so it is computed once and
445	     * stored on the owner.
446	     */
447	    private boolean computeBulkSignupWarning(Owner owner) {
448	        LocalDate registrationDate = owner.getRegistrationDate();
449	        if (registrationDate == null) {
450	            return false;
451	        }
452	        long count = ownerRepository.findAll().stream()
453	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
454	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
455	            .count();
456	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
457	    }
